import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class PublicMethods {

    public String method1() {
        return "Hello, World!";
    }

    public int method2(int[] array) {
        return array.length;
    }

    public String[] method3(String message) {
        String[] words = message.split(" ");
        StringBuilder sb = new StringBuilder();
        for (String word : words) {
            sb.append(word).append(" ");
        }
        return sb.toString().split(" ");
    }

    @Test
    public void testMethod1() {
        assertEquals(method1(), "Hello, World!");
    }

    @Test
    public void testMethod2() {
        assertEquals(5, method2(new int[]{}));
    }

    @Test
    public void testMethod4() {
        String result = method4(5);
        assertEquals("10", result.replaceAll("[^0-9]", ""));
    }

    @Test
    public void testMethod3() {
        String[] result = method3("Hello, World!");
        assertEquals("H e l l o  W o r l d", result);
    }
}
